quests[78222] = { id = 78222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78223] = { id = 78223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of The Knights of the Ebon Blade, you have been called upon to take arms and aid in the Alliance's campaign in defeating the Lich King!", sourceObjective = "Use the scroll of teleportation from your inventory to reach Northrend and speak to the Image of Archmage Modera.", completion = "Greetings, {class} and welcome to the frozen lands of  Northrend. You have arrived at the perfect time. We have much to discuss regarding getting you to the floating city of Dalaran!", sourceObjectiveStatus = "unverified-source-field" }
quests[78224] = { id = 78224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78225] = { id = 78225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of The Knights of the Ebon Bladel, you have been called upon to take arms and aid in the Horde's campaign in defeating the Lich King!", sourceObjective = "Use the scroll of teleportation from your inventory to reach Northrend and speak to the Image of Archmage Aethas Sunreaver.", completion = "Greetings, {class} and welcome to the frozen lands of  Northrend. You have arrived at the perfect time. We have much to discuss regarding getting you to the floating city of Dalaran!", sourceObjectiveStatus = "unverified-source-field" }
