quests[78752] = { id = 78752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Titan Rune Protocol Gamma", description = "The Lich King's presence mustn't extend any further! \n\nThe Council of Six has decreed that any strong enough fighter should take up arms and aid in keeping Azeroth safe!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Defiler's Medallion from any final dungeon boss. \n\nThis quest may only be completed on any Titan Rune Protocol Gamma dungeon difficulty.", progress = "We speak again, {name}. Does this mean you were successful with your duties?", completion = "What evil lies within this!  I will bring this back to \n\nThe Council of Six to investigate further.", sourceObjectiveStatus = "unverified-source-field" }
quests[78753] = { id = 78753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Threats to Azeroth", description = "We must continue putting pressure on all fronts!\n\nThe Council of Six has decreed that any willing fighter should take up arms and aid in keeping Azeroth safe!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Mysterious Artifact from any final dungeon boss. \n\nThis quest may only be completed on any Heroic dungeon difficulty.", progress = "Is something the matter? Why have you not dispatched any of these threats?", completion = "What an interesting find! I will bring this back to \n\nThe Council of Six to investigate further.", sourceObjectiveStatus = "unverified-source-field" }
quests[82948] = { id = 82948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call Board", sourceObjective = "Head to the Trade District in Stormwind and speak to Melris Malagan.", completion = "Well met, {race}. I see that you have answered King Wrynn's call.\n\nBeside me is the Hero's Call Board, which holds the current list of mandates. Take a look and decide which of them you will take on.", sourceObjectiveStatus = "unverified-source-field" }
quests[82949] = { id = 82949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command Board", sourceObjective = "Head to the Valley of Strength in Orgrimmar and speak to the Warchief's Herald.", completion = "Lok'tar, {race}. I see that you have answered the Warchief's call.\n\nBeside me is the Warchief's Command Board, which holds the current list of mandates. Take a look and decide which of them you will take on.", sourceObjectiveStatus = "unverified-source-field" }
quests[82981] = { id = 82981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!" }
